alter table public.restaurant_settings add column if not exists security_discount_password text; create or replace function public.authorize_discount(p_password text,p_discount_type text,p_discount_value numeric,p_subtotal numeric,p_reason text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_expected text;v_amount numeric;begin if v_user is null or not public.has_permission(v_user,'discount.apply') then raise exception 'Discount not permitted';end if;if coalesce(p_discount_value,0)<=0 then return jsonb_build_object('authorized',true,'discount_amount',0);end if;select security_discount_password into v_expected from public.restaurant_settings order by created_at limit 1;if v_expected is null then raise exception 'Discount authorization password is not configured';end if;if p_password is distinct from v_expected then raise exception 'Invalid discount authorization password';end if;if btrim(coalesce(p_reason,''))='' then raise exception 'Discount reason is required';end if;if p_discount_type not in ('fixed','percentage') then raise exception 'Invalid discount type';end if;if p_discount_type='percentage' then if p_discount_value>100 then raise exception 'Invalid discount percentage';end if;v_amount:=p_subtotal*p_discount_value/100;else v_amount:=p_discount_value;end if;if v_amount>p_subtotal then raise exception 'Discount cannot exceed subtotal';end if;return jsonb_build_object('authorized',true,'discount_amount',v_amount);end $$; revoke all on function public.authorize_discount(text,text,numeric,numeric,text) from public,anon; grant execute on function public.authorize_discount(text,text,numeric,numeric,text) to authenticated;